import React, { useState, useEffect } from "react";
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { getAuth, signInWithEmailAndPassword, signOut } from "firebase/auth";
import "./ManageStudents.css";

const AdminManageStudents = () => {
  const [students, setStudents] = useState([]);
  const [form, setForm] = useState({
    name: "",
    email: "",
    username: "",
    password: "",
    studentClass: "",
  });
  const [editId, setEditId] = useState(null);
  const [user, setUser] = useState(null);
  const [authError, setAuthError] = useState("");

  const studentsCollectionRef = collection(db, "students");
  const auth = getAuth();

  // Fetch students from Firestore
  const fetchStudents = async () => {
    const data = await getDocs(studentsCollectionRef);
    setStudents(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(setUser);
    return () => unsubscribe();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const addOrUpdateStudent = async (e) => {
    e.preventDefault();
    if (editId) {
      const studentDoc = doc(db, "students", editId);
      await updateDoc(studentDoc, form);
    } else {
      await addDoc(studentsCollectionRef, form);
    }
    fetchStudents();
    setForm({ name: "", email: "", username: "", password: "", studentClass: "" });
    setEditId(null);
  };

  const deleteStudent = async (id) => {
    const studentDoc = doc(db, "students", id);
    await deleteDoc(studentDoc);
    fetchStudents();
  };

  const editStudent = (student) => {
    setForm(student);
    setEditId(student.id);
  };

  const login = async (email, password) => {
    try {
      await signInWithEmailAndPassword(auth, email, password);
      setAuthError("");
    } catch (error) {
      setAuthError("Failed to log in. Please check your credentials.");
    }
  };

  const logout = async () => {
    await signOut(auth);
  };

  return (
    <div className="manage-students-container">
      {user ? (
        <>
          <h2>Manage Students</h2>
          <button onClick={logout} className="logout-btn">Logout</button>

          <form onSubmit={addOrUpdateStudent} className="student-form">
            <label htmlFor="name">Name:</label>
            <input
              type="text"
              id="name"
              name="name"
              value={form.name}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              name="email"
              value={form.email}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="username">Username:</label>
            <input
              type="text"
              id="username"
              name="username"
              value={form.username}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              name="password"
              value={form.password}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="studentClass">Class:</label>
            <select
              id="studentClass"
              name="studentClass"
              value={form.studentClass}
              onChange={handleInputChange}
              required
            >
              <option value="" disabled>Select Class</option>
              <option value="Primary 1">Primary 1</option>
              <option value="Primary 2">Primary 2</option>
              <option value="Primary 3">Primary 3</option>
              <option value="Primary 4">Primary 4</option>
              <option value="Primary 5">Primary 5</option>
              <option value="Primary 6">Primary 6</option>
              <option value="JSS 1">JSS 1</option>
              <option value="JSS 2">JSS 2</option>
              <option value="JSS 3">JSS 3</option>
              <option value="SSS 1">SSS 1</option>
              <option value="SSS 2">SSS 2</option>
              <option value="SSS 3">SSS 3</option>
            </select>

            <button type="submit" className="form-btn">
              {editId ? "Update Student" : "Add Student"}
            </button>
          </form>

          <table className="students-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Username</th>
                <th>Class</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {students.map((student) => (
                <tr key={student.id}>
                  <td>{student.name}</td>
                  <td>{student.email}</td>
                  <td>{student.username}</td>
                  <td>{student.studentClass}</td>
                  <td>
                    <button onClick={() => editStudent(student)} className="edit-btn">Edit</button>
                    <button onClick={() => deleteStudent(student.id)} className="delete-btn">Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      ) : (
        <div className="login-container">
          <h2>Login</h2>
          {authError && <p className="error">{authError}</p>}
          <form
            onSubmit={(e) => {
              e.preventDefault();
              login(form.email, form.password);
            }}
            className="login-form"
          >
            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              name="email"
              value={form.email}
              onChange={handleInputChange}
              required
            />

            <label htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              name="password"
              value={form.password}
              onChange={handleInputChange}
              required
            />

            <button type="submit" className="login-btn">Login</button>
          </form>
        </div>
      )}
    </div>
  );
};

export default AdminManageStudents;
